        case ("help_mode_map")
            entry%file = "help_mode_fm.f90"
            entry%fortran = "help_mode_map"
            entry%doc = "Keymap for Help mode."
        case ("history_add_new_input")
            entry%file = "minibuf_fm.f90"
            entry%fortran = "history_add_new_input"
