                        "variable `search_whitespace_regexp'.  If the value is false, each"//LF// &
                        "space you type matches literally, against one space.  You can"//LF// &
                        "toggle the value of this variable by the command"//LF// &
                        "`isearch_toggle_lax_whitespace', usually bound to `M-s SPC' during"//LF// &
                        "isearch."
        case ("isearch_mode_map")
            entry%file = "isearch_fm.f90"
            entry%fortran = "isearch_mode_map"
            entry%doc = "Keymap for `isearch_mode'."
        case ("isearch_regexp_lax_whitespace")
            entry%file = "isearch_fm.f90"
            entry%fortran = "isearch_regexp_lax_whitespace"
            entry%original = ".false."
            entry%value = repr(isearch_regexp_lax_whitespace)
            entry%doc = "If true, a space will match a sequence of whitespace chars."//LF// &
                        "When you enter a space or spaces in regexp incremental search, it"//LF// &
                        "will match any sequence matched by the regexp defined by the"//LF// &
                        "variable `search_whitespace_regexp'.  If the value is false, each"//LF// &
                        "space you type matches literally, against one space.  You can"//LF// &
                        "toggle the value of this variable by the command"//LF// &
                        "`isearch_toggle_lax_whitespace', usually bound to `M-s SPC' during"//LF// &
                        "isearch."
        case ("jit_lock_chunk_size")
            entry%file = "jit_lock_fm.f90"
            entry%fortran = "jit_lock_chunk_size"
            entry%original = "1500"
            entry%value = repr(jit_lock_chunk_size)
            entry%doc = "Jit-lock asks to fontify chunks of at most this many characters at"//LF// &
                        "a time."//LF// &
                        ""//LF// &
                        "The actual size of the fontified chunk of text can be different,"//LF// &
                        "depending on what the `fontification_functions' actually decide to"//LF// &
                        "do."//LF// &
                        ""//LF// &
                        "This variable controls both display-time and stealth"//LF// &
