        case ("kmacro_keymap")
            entry%file = "kmacro_fm.f90"
            entry%fortran = "kmacro_keymap"
            entry%doc = "Keymap for keyboard macro commands."
        case ("kmacro_last_counter")
            entry%file = "kmacro_fm.f90"
            entry%fortran = "kmacro_last_counter"
